// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {
    AccessControlEnumerable
} from "@openzeppelin/contracts/access/extensions/AccessControlEnumerable.sol";
import { ISubAccountFactory } from "../interfaces/ISubAccountFactory.sol";
import { SubAccount } from "./SubAccount.sol";
import { Roles } from "../access/Roles.sol";

/// @title SubAccountFactory
/// @notice 「办卡机」:CREATE2 + userWallet 派生 salt,地址可预测且幂等去重(1 钱包 : 1 子账户)。
contract SubAccountFactory is ISubAccountFactory, AccessControlEnumerable {
    mapping(address => address) private _subAccountOf;
    /// @notice 反查:某地址是否为本工厂签发的子账户。
    /// @dev 金库据此校验发放/派付的收款方——只有正查(`subAccountOf`)的话,
    ///      拿到一个地址无法判断它是不是子账户,任意 EOA 就能当收款方。
    mapping(address => bool) public isSubAccount;

    /// @notice 新建子账户时写入的平台管理员地址(子账户构造时读取)
    address public platformAdmin;

    /// @notice 资金池地址。子账户的受控出口(`payToTreasury`/`recycleToTreasury`)**动态读取**
    ///         本字段决定去向——与 `platformAdmin` 同款模式:轮换只需在工厂上一笔交易,即对
    ///         全部存量子账户立即生效,不必逐个改。
    address public treasury;

    event PlatformAdminUpdated(address indexed previousAdmin, address indexed newAdmin);
    event TreasuryUpdated(address indexed previousTreasury, address indexed newTreasury);

    constructor(address admin) {
        require(admin != address(0), "zero admin");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        platformAdmin = admin;
        emit PlatformAdminUpdated(address(0), admin);
    }

    /// @notice 设置/轮换资金池地址。**对全部存量子账户立即生效**。
    function setTreasury(address newTreasury) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newTreasury != address(0), "zero treasury");
        emit TreasuryUpdated(treasury, newTreasury);
        treasury = newTreasury;
    }

    /// @notice 更新后续新建子账户使用的平台管理员(不影响已创建账户)
    function setPlatformAdmin(address newAdmin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newAdmin != address(0), "zero admin");
        emit PlatformAdminUpdated(platformAdmin, newAdmin);
        platformAdmin = newAdmin;
    }

    /// @notice 办卡。限活动服务调用(D2):办卡是平台行为,开放调用会被抢跑用于批量建号骚扰。
    function createSubAccount(address userWallet)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        returns (address subAccount)
    {
        require(userWallet != address(0), "zero userWallet");

        address existing = _subAccountOf[userWallet];
        if (existing != address(0)) {
            return existing; // 幂等:已办卡则返回既有
        }

        bytes32 salt = _salt(userWallet);
        subAccount = address(new SubAccount{ salt: salt }(userWallet));

        _subAccountOf[userWallet] = subAccount;
        isSubAccount[subAccount] = true;
        emit SubAccountCreated(userWallet, subAccount);
    }

    function subAccountOf(address userWallet) external view returns (address) {
        return _subAccountOf[userWallet];
    }

    function hasSubAccount(address userWallet) external view returns (bool) {
        return _subAccountOf[userWallet] != address(0);
    }

    /// @notice 创建前预测子账户地址(CREATE2)
    function predictSubAccount(address userWallet) external view returns (address) {
        bytes32 salt = _salt(userWallet);
        bytes32 initCodeHash =
            keccak256(abi.encodePacked(type(SubAccount).creationCode, abi.encode(userWallet)));
        return address(
            uint160(
                uint256(
                    keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, initCodeHash))
                )
            )
        );
    }

    function _salt(address userWallet) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("HSK_PREDICT_SUBACCOUNT", userWallet));
    }
}

