pragma solidity ^0.8.24;

import { IAccessControl } from "@openzeppelin/contracts/access/IAccessControl.sol";
import { ISubAccount } from "../interfaces/ISubAccount.sol";
import { ISubAccountFactory } from "../interfaces/ISubAccountFactory.sol";
import { Roles } from "../access/Roles.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title SubAccount
/// @notice 每用户托管子账户:持真实可提资产(USDT/桥),平台 admin 管进出,用户 EOA 无任何入口(BR-03/06)。
/// @dev 构造参数只含 userWallet,保证 CREATE2 地址稳定。
///      **admin 不做构造快照**,而是每次动态读 `factory.platformAdmin()`(D1):
///      - 平台密钥轮换/迁多签:工厂上一笔 setPlatformAdmin 即对全部存量子账户生效;
///      - 旧密钥泄露:轮换后立即失效,不会继续持有存量资产的支配权;
///      - 代价是每次校验多一次 external call(~2.6k gas),对 admin-only 的低频提现路径可忽略。
///      `factory` 是 immutable,故无新增信任面。
///      提现是本套合约里唯一做真实 external 转账(native `.call` / ERC20 `safeTransfer`)之处,
///      加 `nonReentrant` 作纵深防御:虽提现为 `onlyAdmin`(恶意接收方无法自行回调提现、实际
///      不可利用),但对做外部调用的资金函数一律上重入锁,消除审计与未来改动的隐患。
contract SubAccount is ISubAccount, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable userWallet;
    address public immutable factory;

    modifier onlyAdmin() {
        require(msg.sender == ISubAccountFactory(factory).platformAdmin(), "not admin");
        _;
    }

    /// @dev 角色注册表复用**工厂**(它本身就是 AccessControl)。好处:角色授予/撤销只在工厂
    ///      一处操作,即对全部存量子账户立即生效;子账户不新增任何状态。与 `platformAdmin`
    ///      的动态读取是同一套模式(D1)。
    modifier onlyFactoryRole(bytes32 role) {
        require(IAccessControl(factory).hasRole(role, msg.sender), "unauthorized");
        _;
    }

    constructor(address _userWallet) {
        userWallet = _userWallet;
        factory = msg.sender;
    }

    receive() external payable {
        emit NativeReceived(msg.sender, msg.value);
    }

    /// @inheritdoc ISubAccount
    /// @dev 始终反映工厂当前的 platformAdmin(无本地快照)。
    function admin() external view returns (address) {
        return ISubAccountFactory(factory).platformAdmin();
    }

    function withdrawNative(address to, uint256 amount) external onlyAdmin nonReentrant {
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "native transfer failed");
        // 标为 ADMIN_RETURN:这是唯一的任意去向出口,日志必须一眼可辨,
        // 审计时这类记录要单独核对(为什么退、退给谁),混在普通出账里会被淹没。
        emit NativeWithdrawn(to, amount, "ADMIN_RETURN");
    }

    function withdrawERC20(address token, address to, uint256 amount)
        external
        onlyAdmin
        nonReentrant
    {
        IERC20(token).safeTransfer(to, amount);
        emit ERC20Withdrawn(token, to, amount);
    }

    // ─────────────────────────── 受控出口 ───────────────────────────
    //
    // 以下三个函数**都不接受目标地址参数**——去向由合约按用途写死。这是整套设计的安全
    // 核心:业务角色的私钥放在服务器上(热钱包),即便泄露,攻击者能做的也只是把用户的钱
    // 推进金库、或退回用户**自己**的钱包,**没有任何一条路通向攻击者自己**。
    //
    // 唯一的任意去向出口是上面的 `withdrawNative`/`withdrawERC20`,仅 `platformAdmin`
    // (冷钱包/多签)可用,专供误转资产原路退回。那把钥匙是本设计里唯一需要靠保管来防守的。
    //
    // gas 由**发起交易的调用方**支付,子账户自身无需持有任何 gas——故可精确清零、
    // 可全额转出,不存在 EOA 方案里"余额全押就付不起 gas"的问题。

    /// @notice 下注扣款:子账户 → 金库。去向 = `factory.treasury()`,调用方改不了。
    function payToTreasury(uint256 amount)
        external
        onlyFactoryRole(Roles.MARKET_ROLE)
        nonReentrant
    {
        require(address(this).balance >= amount, "insufficient balance");
        _sendTo(ISubAccountFactory(factory).treasury(), amount, "BET");
    }

    /// @notice 活动结束回收:把剩余全部推进金库。余额为 0 时是 no-op(不 revert),
    ///         便于运营对全量用户无差别扫一遍。
    function recycleToTreasury()
        external
        onlyFactoryRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
    {
        uint256 bal = address(this).balance;
        if (bal == 0) return;
        _sendTo(ISubAccountFactory(factory).treasury(), bal, "RECYCLE");
    }

    /// @notice 平台收费(报告解锁一类的用户付费):子账户 → 金库。去向同样写死。
    /// @dev 为什么不复用 `payToTreasury`:那条出口的角色是 `MARKET_ROLE`,而该角色**只有
    ///      `PredictionMarket` 合约持有**——"让子账户付款必须经过市场的成交确认"是一条已写进
    ///      审计文档、并有测试守护的不变量,不该为了收费把它撑开。
    ///
    ///      为什么给 `ACTIVITY_SERVICE_ROLE` 开这条是安全的:该角色**已经**能调
    ///      `recycleToTreasury()` 把整个子账户扫空进金库。本函数去向相同、金额更小,
    ///      **新增权限为零**,严格弱于它已有的能力。
    ///
    ///      reason 写死为 `FEE` 而不做成入参:入参会让持有该角色的热钥匙把一笔收费标成
    ///      别的用途,日志的分类价值就没了。具体是哪笔收费由 txHash 关联链下意图,
    ///      与 `BET` 不标明是哪个盘口同理。
    function collectFromUser(uint256 amount)
        external
        onlyFactoryRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
    {
        require(address(this).balance >= amount, "insufficient balance");
        _sendTo(ISubAccountFactory(factory).treasury(), amount, "FEE");
    }

    /// @notice 提现:只能回到 `userWallet`(immutable,部署时绑定,谁都改不了)。
    /// @dev 本期活动不启用(HSK 不可提现),保留接口供后续真实资产场景。
    function withdrawToUser(uint256 amount)
        external
        onlyFactoryRole(Roles.SETTLER_ROLE)
        nonReentrant
    {
        require(address(this).balance >= amount, "insufficient balance");
        _sendTo(userWallet, amount, "WITHDRAW");
    }

    /// @dev `reason` 由**合约自己**按出口写死,不是调用方传的参数——否则热钱包可以把
    ///      一笔回收标成下注,日志的分类价值就没了。
    function _sendTo(address to, uint256 amount, bytes32 reason) internal {
        require(to != address(0), "zero destination");
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
        emit NativeWithdrawn(to, amount, reason);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title ISubAccount
/// @notice 每用户托管子账户接口:持真实可提资产,仅平台 admin 可动用。
/// @dev admin 不在本合约存储,而是动态读工厂的 platformAdmin()——
///      平台密钥轮换只需在工厂上一笔交易即可对全部存量子账户生效(D1)。
interface ISubAccount {
    event NativeReceived(address indexed from, uint256 amount);
    /// @notice 出账。`reason` 标明用途:`BET` 下注 / `FEE` 平台收费 / `RECYCLE` 活动回收 /
    ///         `WITHDRAW` 提现给用户 / `ADMIN_RETURN` 误转资产原路退回。
    /// @dev 没有 reason 时,下注与回收在日志里完全相同(都是「子账户 → 金库」,金额还可能一样),
    ///      只能靠"同一个 tx 里有没有 Market 事件"去反推。带上之后,子账户自己的日志就是一份
    ///      完整可读的资金流水,用户与审计方不必跨合约拼接即可分类每一笔出账。
    event NativeWithdrawn(address indexed to, uint256 amount, bytes32 reason);
    event ERC20Withdrawn(address indexed token, address indexed to, uint256 amount);

    function userWallet() external view returns (address);
    function factory() external view returns (address);
    function admin() external view returns (address);
    function withdrawNative(address to, uint256 amount) external;
    function withdrawERC20(address token, address to, uint256 amount) external;

    /// 受控出口:去向由合约写死,调用方只能触发。
    function payToTreasury(uint256 amount) external;
    function collectFromUser(uint256 amount) external;
    function recycleToTreasury() external;
    function withdrawToUser(uint256 amount) external;
}

