/// @title ISubAccountFactory
/// @notice 托管子账户工厂接口:CREATE2 幂等办卡(1 用户 : 1 子账户)。
interface ISubAccountFactory {
    event SubAccountCreated(address indexed userWallet, address indexed subAccount);

    function createSubAccount(address userWallet) external returns (address);
    function subAccountOf(address userWallet) external view returns (address);
    function hasSubAccount(address userWallet) external view returns (bool);
    function predictSubAccount(address userWallet) external view returns (address);
    function platformAdmin() external view returns (address);
    function treasury() external view returns (address);
}
